B=[['希腊 minthe；拉丁 menta / mentha','薄荷；更早来源不确定']]
M=B+[['日耳曼语借入拉丁植物名 → 古英语 minte','薄荷'],['中古英语 mynte → 英语 mint','薄荷及其风味']]
W=[
E('mint','/mɪnt/','薄荷；薄荷糖；另有铸币厂、铸造等不同来源的意思','闻到清凉草香的那片叶子是这里的 mint；铸币厂里的 mint 则要另走一条词源线。','薄荷义经古英语 minte、日耳曼语形式接拉丁 menta/mentha，与希腊 minthe 有关。铸币义经古英语 mynet 接拉丁 moneta，不能从薄荷解释。',M+[['同形异源：拉丁 moneta → 古英语 mynet → mint','硬币、造币处 → 铸币厂；铸造']],'fresh mint 是鲜薄荷；a mint 可以是一颗薄荷糖。另一条线里 mint coins 是铸造硬币，a mint 是造币厂；in mint condition 表示像刚出厂一样完好，借的是新铸硬币的状态。','mint leaves；mint tea；a mint；mint coins；in mint condition。','同一个拼写能装两套来源。make a mint 是赚大钱，也属于金钱这条线，不能拿清凉、植物去硬推。',('She added fresh mint to the salad.','她往沙拉里加了鲜薄荷。'),('Would you like a mint after the meal?','饭后要来一颗薄荷糖吗？'),('The museum displays coins minted in the city.','博物馆展出了在这座城市铸造的硬币。'),('The old camera is still in mint condition.','这台老相机仍完好如新。'),sources=['https://en.wiktionary.org/wiki/mint']),
E('menthol','英 /ˈmenθɒl/；美 /ˈmenθɔːl/','薄荷醇','把薄荷带来的清凉感联想到一种具体成分；它是化合物，不是整片薄荷叶。','名称以拉丁 mentha 薄荷为基础；借德语 Menthol 的历史说法中，末尾联系 oleum 油。现代化学里也按 menth- + -ol 醇类后缀理解。',B+[['德语 Menthol → 英语 menthol','以薄荷为基础命名的化合物'],['现代化学分析 menth- + -ol','薄荷醇；醇类名称']],'menthol 可从薄荷油获得，也可合成，常见于口腔护理等产品的成分表。它能带来凉的感觉；“觉得凉”不等于物体真的变成冰冷，也不等于薄荷油只含这一种物质。','menthol flavor；menthol crystals；contains menthol。','mint 是植物或风味的常用词；menthol 是具体化学物质。-ol 在这里表示醇类，不代表食品里添加的饮用酒精。',('The label lists menthol as one of the ingredients.','标签把薄荷醇列为其中一种成分。'),('Menthol gives the product a cooling sensation.','薄荷醇让这种产品带来清凉感。'),sources=['https://www.etymonline.com/word/menthol','https://en.wiktionary.org/wiki/menthol','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/menthol']),
E('spearmint','英 /ˈspɪəmɪnt/；美 /ˈspɪrmɪnt/','留兰香；绿薄荷','超市口香糖或茶包装上常见的一种薄荷名，它是具体品种，不是所有薄荷的统称。','英语 spear 与 mint 组成；词源资料把 spear 联系到植物尖长的花序或 spire 形态，不宜只凭现代 spear“矛”编一个故事。',M+[['spear〔植物尖长形态〕+ mint → spearmint','留兰香这一薄荷名称']],'spearmint tea 是留兰香茶；spearmint gum 是留兰香味口香糖。植物名通常对应 Mentha spicata。购物或阅读时，先认出它是 mint 大类中的一种就很实用。','spearmint tea；spearmint gum；spearmint leaves。','spearmint 与 peppermint 都是薄荷类，却不是同一个植物名称；英语包装可能把两种风味分开标示。',('She grows spearmint in a pot beside the kitchen window.','她在厨房窗边的花盆里种了留兰香。'),('I chose the spearmint gum instead of the peppermint flavor.','我选了留兰香味口香糖，没有选胡椒薄荷味。'),sources=['https://en.wiktionary.org/wiki/spearmint','https://www.etymonline.com/word/spearmint','https://www.merriam-webster.com/dictionary/spearmint']),
E('minty','/ˈmɪnti/','有薄荷味的；带薄荷般清凉气味的','闻起来或尝起来让人想到薄荷，即使眼前并没有一片叶子。','mint 植物或风味义 + -y，表示具有这种味道或特点；这里不接铸币义。',M+[['mint + -y → minty','带薄荷味的']],'a minty taste 是薄荷味，a minty smell 是薄荷气味。它描述感官印象，可以用于牙膏、口香糖、茶或空气中的气味；是否含天然薄荷，要另看成分。','a minty flavor；a minty taste；a fresh minty smell。','minty 说像薄荷；fresh 说清新，范围更宽。清新不一定是薄荷味，有薄荷味也不能单凭形容词判断具体配方。',('The toothpaste has a strong minty flavor.','这款牙膏有浓浓的薄荷味。'),('Crushing the leaves released a fresh, minty smell.','揉碎叶子后，一股清新的薄荷香散发出来。'),sources=['https://en.wiktionary.org/wiki/minty','https://scrabble.merriam.com/finder/minty'])
]
ROOT=dict(id='C0746',meaning='薄荷',core='MINTH / MENTH / MINT = MINT',image='捏一片薄荷叶，想到它的草香与清凉感：植物是 mint，具体种类有 peppermint、spearmint，气味像它叫 minty，成分里可见 menthol。',intro='这组主要是植物名的历史变化。希腊 minthe 与拉丁 menta/mentha 相关；拉丁植物名被日耳曼语言借入，最后形成英语 mint。更早的地中海来源不确定，无须强行追到一个万能动作。',forms='mint 是经过历史音形变化的常用英语词；menthol 保留 menth-。peppermint、spearmint、minty 是现代较透明的组合或派生。mint 的铸币、赚大钱与崭新状态另接 moneta，必须分源。',branches=[['植物与品种','mint, peppermint, spearmint'],['风味与成分','minty, menthol']],contrasts='mint 不是总指一种固定植物；spearmint 与 peppermint 是不同名称。minty 不保证天然成分；menthol 不等于整个薄荷油。铸币厂 mint 与植物无关。',practice='The minty flavor comes from spearmint, not from a coin mint.\n\n这种薄荷味来自留兰香，当然不是来自造币厂。',words=[x['word'] for x in W]+['peppermint'],exclude={w:'植物学属名或低频专名，本轮先略。' for w in ['Acanthomintha','Mentha','mentha','Minthostachys']})
